create table if not exists public.mapping_import_combos (
  import_batch_id uuid not null references public.mapping_import_batches(import_batch_id) on delete cascade,
  combo_id smallint not null,
  match_tier text null,
  match_score numeric null,
  primary key (import_batch_id, combo_id)
);

create table if not exists public.mapping_import_hash_chunks (
  import_batch_id uuid not null references public.mapping_import_batches(import_batch_id) on delete cascade,
  combo_id smallint not null,
  chunk_no integer not null,
  base64_data text not null,
  primary key (import_batch_id, combo_id, chunk_no),
  foreign key (import_batch_id, combo_id)
    references public.mapping_import_combos(import_batch_id, combo_id) on delete cascade
);

create table if not exists public.mapping_import_hashes (
  import_batch_id uuid not null references public.mapping_import_batches(import_batch_id) on delete cascade,
  hash_hex text not null,
  combo_id smallint not null,
  primary key (import_batch_id, hash_hex),
  foreign key (import_batch_id, combo_id)
    references public.mapping_import_combos(import_batch_id, combo_id) on delete cascade
);

create or replace function public.expand_mapping_import_hashes(p_batch_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  payload bytea;
  i integer;
  inserted_count integer := 0;
begin
  delete from public.mapping_import_hashes where import_batch_id = p_batch_id;

  for r in
    select c.combo_id,
           string_agg(c.base64_data, '' order by c.chunk_no) as combined
    from public.mapping_import_hash_chunks c
    where c.import_batch_id = p_batch_id
    group by c.combo_id
  loop
    payload := decode(r.combined, 'base64');
    if octet_length(payload) % 8 <> 0 then
      raise exception 'invalid hash payload length for batch %, combo %', p_batch_id, r.combo_id;
    end if;
    for i in 0..(octet_length(payload) / 8 - 1) loop
      insert into public.mapping_import_hashes(import_batch_id, hash_hex, combo_id)
      values (p_batch_id, encode(substring(payload from i * 8 + 1 for 8), 'hex'), r.combo_id)
      on conflict (import_batch_id, hash_hex) do update set combo_id = excluded.combo_id;
      inserted_count := inserted_count + 1;
    end loop;
  end loop;
  return inserted_count;
end;
$$;

revoke all on function public.expand_mapping_import_hashes(uuid) from public, anon, authenticated;

alter table public.mapping_import_combos enable row level security;
alter table public.mapping_import_hash_chunks enable row level security;
alter table public.mapping_import_hashes enable row level security;
